/* Fresh, scenario-specific example records for the local evaluation Mock. */
function evSeedScene(scene) {
  if (!['sales', 'procurement'].includes(scene)) throw new Error('不支持的评测场景');
  const sales = scene === 'sales';
  const prefix = sales ? 'SAL' : 'PUR';
  const id = (kind, number) => prefix + '-' + kind + '-' + String(number).padStart(3, '0');
  const agentId = sales ? 'sales-agent-1' : 'procurement-agent-1';
  const appAgentId = sales ? 'sales-app-agent' : 'procurement-app-agent';
  // Keep example creation dates stable within a Shanghai calendar day while
  // covering today, yesterday, the last seven days, and older resources.
  const shanghaiDay = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
  const createdAt = daysAgo => new Date(Date.parse(shanghaiDay + 'T00:00:00Z') - daysAgo * 86400000).toISOString().slice(0, 10) + 'T00:00:00+08:00';
  const taskDays = [0, 1, 4, 10], suiteDays = [0, 1, 4], caseDays = [0, 0, 1, 2, 4, 6, 9, 14];
  const dimension = (name, description, values = ['不符合', '部分符合', '符合']) => ({name, description, values: [...values]});
  const task = (number, name, version, prompt, dimensions, application = false) => ({
    id: id('BT', number), name, agentId: application ? appAgentId : agentId, version,
    prompt: {...prompt}, dimensions, createdAt: createdAt(taskDays[number - 1])
  });
  const makeCase = (number, name, input, expected, tags, version = 'V1', enabled = true) => ({
    id: id('EC', number), name, input, expected, tags: [...tags], version,
    enabled, archived: false, source: '场景示例', createdAt: createdAt(caseDays[number - 1])
  });

  const tasks = sales ? [
    task(1, '生成渠道分货方案', 'V3', {
      description: '根据经销商已确认订单、可供库存和渠道规则，生成本周可评审的分货方案。',
      inScope: '核对订单与库存，按已确认规则分配商品，输出分配量、需求缺口和规则依据。',
      outScope: '不自动锁库、下发出库单或批准方案；不使用未确认规则，不编造库存。',
      input: '订单编号、经销商、商品编码、需求数量、可供库存、渠道优先级及规则版本。',
      completion: '逐订单展示需求量、分配量、缺口和依据；每种商品的分配总量不超过可供库存，方案等待业务确认。',
      excellence: '清晰解释分配顺序与缺口原因，关联订单、库存快照和规则版本，列出待确认事项。',
      positive: '商品 A 库存 1,000 件，华东、华南、华北订单分别为 420、330、250 件：分配 420、330、250 件，无缺口，并列明订单与库存依据。',
      negative: '库存仅 1,000 件却分配 1,100 件；未展示缺口与规则来源，直接通知仓库执行。'
    }, [
      dimension('业务正确性', '分配结果是否满足库存上限、订单需求和渠道规则。'),
      dimension('结果完整性', '是否包含订单、需求量、分配量、缺口与待确认状态。'),
      dimension('依据可追溯', '是否明确引用库存快照和已确认的规则版本。', ['缺失', '部分可追溯', '完整可追溯'])
    ]),
    task(2, '库存缺口与优先级处置', 'V2', {
      description: '在可供库存小于订单需求时，按渠道优先级形成分货与缺口处置建议。',
      inScope: '计算需求缺口、保障已确认的优先订单、比较可行分配，并说明未满足需求。',
      outScope: '不自行调整渠道等级，不以预计到货替代现有库存，不直接批准补货或调拨。',
      input: '逐渠道需求、已确认订单标记、可供库存及明确的分配优先级。',
      completion: '优先级执行正确，需求量等于分配量加缺口；汇总总缺口，并保留人工决策节点。',
      excellence: '提供可解释的优先级依据，说明受影响订单及补货、调拨等备选建议的前提。',
      positive: '库存 800 件，华东、华南、华北需求 500、400、300 件，优先级依次降低：分配 500、300、0 件，缺口 0、100、300 件。',
      negative: '忽略渠道优先级平均分配，或把尚未确认到货的 400 件计入可供库存，声称没有缺口。'
    }, [
      dimension('优先级遵循', '分配顺序是否符合输入中已确认的渠道与订单优先级。'),
      dimension('缺口计算', '逐订单与汇总缺口是否准确且相互一致。'),
      dimension('建议可执行性', '处置建议是否明确前提、责任人与待确认事项。', ['不可执行', '需补充', '可评审'])
    ]),
    task(3, '异常输入与规则冲突校验', 'V1', {
      description: '识别分货输入中的缺失字段和冲突规则，在计算前给出明确的补充与确认请求。',
      inScope: '校验商品编码、订单数量和库存字段，识别规则优先级冲突并说明影响范围。',
      outScope: '不猜测缺失商品编码，不默认覆盖已确认规则，不在关键字段缺失时继续分货。',
      input: '待评测订单、商品与库存字段、所有适用规则及其版本和确认状态。',
      completion: '准确列出缺失或冲突项，暂停受影响部分，说明需要谁补充什么数据或确认哪条规则。',
      excellence: '区分阻断项与可继续项，定位受影响订单，并给出最小补充资料清单。',
      positive: '订单缺失商品编码：明确指出无法匹配库存，请补充编码后再分配，不按相似商品名称推断。',
      negative: '自行填入商品编码，或在两条同优先级分配规则冲突时静默选择其中一条并输出执行方案。'
    }, [
      dimension('异常识别', '是否准确识别关键字段缺失和规则冲突。'),
      dimension('边界遵循', '是否暂停受影响计算并保留业务确认。'),
      dimension('补充请求质量', '请求是否具体、清楚并能推动问题解决。', ['模糊', '基本明确', '明确可操作'])
    ]),
    task(4, '销售应用经营风险复核', 'V2', {
      description: '从销售管理应用视角复核分货方案与异常清单，生成经营风险摘要和负责人待办。',
      inScope: '汇总需求满足率、库存缺口、重点渠道影响和规则待确认项，引用场景内可用的方案证据。',
      outScope: '不代替业务审批，不修改原始订单和分货结果，不将示例风险当成真实经营结论。',
      input: '场景分货方案、订单与渠道汇总、缺口明细、规则冲突和人工确认记录。',
      completion: '生成含风险级别、事实依据、受影响对象、建议动作和责任人的摘要，并标注待确认信息。',
      excellence: '按影响程度排序，区分已验证事实与待确认判断，能追溯到具体订单和方案版本。',
      positive: '重点渠道仍有 300 件缺口且优先级规则待确认：列为高优先级复核项，引用缺口明细，建议销售负责人确认资源处置。',
      negative: '在缺少订单依据时宣称预计损失已确定，或代表销售负责人批准跨渠道调拨。'
    }, [
      dimension('风险覆盖', '是否覆盖缺口、渠道影响与规则确认等关键风险。'),
      dimension('证据一致性', '摘要结论是否与场景方案和异常明细一致。'),
      dimension('决策边界', '是否明确责任人与人工审批边界。', ['越界', '边界不清', '边界清楚'])
    ], true)
  ] : [
    task(1, '多供应商寻源与份额建议', 'V3', {
      description: '根据物料净需求、供应商准入、报价和产能，形成可评审的寻源与采购份额建议。',
      inScope: '核对供应商资格、比较同口径报价与产能，推荐采购量、供应商份额及价格依据。',
      outScope: '不自动定标、签约或下单，不推荐未准入供应商，不编造报价和交付能力。',
      input: '物料编码、净需求、交付日期、合格供应商清单、报价币种与税口径、可供量和交期。',
      completion: '推荐采购量不超过合格供应商可供量，满足需求或明确缺口，输出份额、报价、交期及依据。',
      excellence: '统一报价比较口径，解释供应商选择，列出价格、集中度与交付风险及备选方案。',
      positive: '需求 800 件，合格供应商 A 可供 500 件、B 可供 300 件，均按期交付：建议 A 500 件、B 300 件，列明报价和准入依据。',
      negative: '为补足需求直接推荐未准入供应商，省略税口径和交期差异，或自动提交采购订单。'
    }, [
      dimension('寻源合规性', '推荐供应商是否符合准入条件和采购规则。'),
      dimension('数量正确性', '采购份额是否符合净需求与可供量约束。'),
      dimension('报价可比性', '是否统一币种、税率和计价单位后比较。', ['不可比', '部分可比', '口径一致'])
    ]),
    task(2, '交期风险与替代供应商分析', 'V2', {
      description: '识别交期延迟和供应不足风险，给出符合准入条件的替代供应商与交付建议。',
      inScope: '比较承诺交期与需求日期，计算到期可交量和缺口，评估合格替代来源。',
      outScope: '不隐去延期风险，不把未承诺产能计为确定供给，不自行接受延期或启用未准入供应商。',
      input: '采购需求日期、供应商承诺交期、分批交付量、准入状态及替代供应商的有效报价与产能。',
      completion: '明确延期天数、受影响物料和到期缺口，推荐可用替代来源，无法满足时请求采购负责人确认。',
      excellence: '区分确定可供与待确认可供，比较替代方案的成本、风险和后续确认事项。',
      positive: '需求 600 件，A 仅 400 件能按期交付；合格 B 可按期补充 200 件：建议 A 400、B 200，并保留替代方案审批。',
      negative: 'A 的全部 600 件都晚于需求日期，仍标记为无风险；或选择资料不全的供应商补量。'
    }, [
      dimension('交期识别', '是否识别迟交、分批交付与到期可供量。'),
      dimension('替代可行性', '替代供应商是否合格且具有按期可供能力。'),
      dimension('风险说明', '是否明确缺口、影响与待确认事项。', ['未说明', '部分说明', '清晰完整'])
    ]),
    task(3, '供应商准入与报价冲突校验', 'V1', {
      description: '在寻源推荐前校验关键输入、供应商准入与报价有效性，阻断缺失数据和冲突规则。',
      inScope: '检查物料编码、准入有效期、报价版本、币种税口径和相互冲突的采购规则。',
      outScope: '不替代供应商准入审批，不猜测物料编码，不用过期或未确认报价形成最终推荐。',
      input: '采购需求、供应商准入文件、报价单及版本、规则配置和审批状态。',
      completion: '列出缺失或冲突项，暂停受影响推荐，并说明需要补充的字段、有效文件或规则确认。',
      excellence: '识别风险的影响范围，区分阻断项和可继续项，明确资料责任人与下一步动作。',
      positive: '低价供应商 C 的准入资料已过期：不纳入推荐，列明过期证据并请求补充有效准入文件。',
      negative: '仅因为报价最低就选择未准入供应商，或混用含税价与未税价后直接判定价格优势。'
    }, [
      dimension('准入校验', '是否核对准入有效状态并排除不合规来源。'),
      dimension('输入完整性', '是否识别物料、报价与口径的关键缺失。'),
      dimension('冲突处理', '是否保留冲突证据并等待有权人员确认。', ['直接覆盖', '提示不完整', '明确请求确认'])
    ]),
    task(4, '采购应用供应风险复核', 'V2', {
      description: '从采购管理应用视角汇总寻源方案、供应缺口与合规异常，形成供应风险摘要和待办。',
      inScope: '复核采购份额、供应商集中度、交付缺口与准入异常，并引用场景方案证据。',
      outScope: '不自动批准寻源结果、预算或例外准入，不更改原始采购数据，不隐去待核实风险。',
      input: '寻源方案、供应商份额与报价对比、交期风险清单、准入异常和负责人确认记录。',
      completion: '按风险级别列明物料、供应商、事实依据、建议措施与责任人，标注审批和核实节点。',
      excellence: '区分已验证事实与推测，说明风险之间的依赖，给出有前提的备选采购方案。',
      positive: '关键物料仅单一来源且有 200 件到期缺口：列为高优先级供应风险，引用交付明细，建议采购负责人确认替代来源。',
      negative: '缺少依据就认定供应商违约，或代表采购负责人批准超预算采购及例外准入。'
    }, [
      dimension('风险覆盖', '是否覆盖交付、集中度、报价和合规风险。'),
      dimension('证据一致性', '风险结论是否与寻源方案和异常记录一致。'),
      dimension('决策边界', '是否明确资料责任、审批与人工确认边界。', ['越界', '边界不清', '边界清楚'])
    ], true)
  ];

  const cases = sales ? [
    makeCase(1, '标准库存下的渠道分货', '商品 A 可供库存 1,000 件；已确认订单：华东 420 件、华南 330 件、华北 250 件。按已确认渠道规则生成分货方案，标明依据并等待审批。', '分别分配 420、330、250 件，合计 1,000 件，缺口均为 0；输出订单、商品、库存快照和规则依据，不自动出库。', ['正常流程', '渠道分货'], 'V3'),
    makeCase(2, '库存不足时按优先级分配', '商品 A 库存 800 件；华东需求 500、华南 400、华北 300 件；已确认规则为华东优先于华南、华南优先于华北，按顺序满足需求。', '分配华东 500、华南 300、华北 0 件；对应缺口 0、100、300 件，总缺口 400 件；说明优先级依据和待确认处置建议。', ['库存不足', '优先级', '边界条件'], 'V2'),
    makeCase(3, '订单缺失商品编码', '订单 SO-103 需求 120 件，商品名称为“标准组件”，商品编码为空；库存表包含两个同名但不同编码的商品。请生成分货方案。', '指出商品编码缺失且名称无法唯一匹配；暂停 SO-103 分配，请求补充准确编码，不猜测或合并两个商品的库存。', ['数据缺失', '异常处理'], 'V2'),
    makeCase(4, '同优先级分货规则冲突', '商品 B 库存 100 件，订单合计需求 180 件。两条已生效且同优先级规则分别要求“重点渠道优先”和“按订单时间先到先得”，两者分配结果不同，未配置冲突处理规则。', '列出冲突规则及对订单分配的影响，暂停受影响分配并请求业务负责人确认；不静默覆盖任何一条规则。', ['规则冲突', '人工确认'], 'V1'),
    makeCase(5, '优先保障已确认订单', '商品 C 库存 200 件；已确认订单 SO-201 需求 150 件，普通意向需求 100 件。规则明确先满足已确认订单，再分配剩余库存。', '已确认订单分配 150 件，意向需求分配 50 件并显示 50 件缺口；合计 200 件，说明订单保障规则且等待确认。', ['订单保障', '正常流程'], 'V2'),
    makeCase(6, '零库存时保留完整缺口', '商品 D 可供库存为 0 件，两张有效订单需求分别为 80 和 120 件，预计下周到货但数量尚未确认。请给出本周分货结果。', '两张订单分配均为 0，分别显示 80、120 件缺口，总缺口 200 件；预计到货不计入当前库存，列出待确认补货建议。', ['零库存', '边界条件'], 'V1'),
    makeCase(7, '未确认规则版本复核', '销售规则 V2 已签字确认，V3 草稿尚未审批且调整了渠道优先级。请对同一批订单比较两版影响并说明本次分货应采用的依据。', '明确 V2 为当前有效依据，V3 仅用于影响分析；比较差异并等待业务负责人决定是否发布 V3，不直接按草稿执行。', ['版本回归', '规则待确认'], 'V3', false),
    makeCase(8, '应用级经营风险摘要', '销售分货方案 V3 中，重点渠道仍有 300 件缺口；另有两张订单因规则冲突暂停。请从销售管理应用视角生成风险摘要和负责人待办。', '覆盖缺口与规则冲突两类风险，引用方案版本及订单证据，列明负责人、建议动作和确认节点；不替代业务审批或执行调拨。', ['应用复核', '经营风险'], 'V2', false)
  ] : [
    makeCase(1, '合格双供应商寻源分配', '物料 M-001 净需求 800 件，要求 11 月 15 日交付；已准入 A、B 均能按期交付，A 可供 500 件、含税单价 100 元，B 可供 300 件、含税单价 103 元。', '建议 A 500 件、B 300 件，合计 800 件；份额为 62.5% 与 37.5%，同口径含税金额 80,900 元；列明报价、准入与交期依据，等待审批。', ['正常流程', '供应商份额'], 'V3'),
    makeCase(2, '供应不足时明确采购缺口', '物料 M-002 净需求 1,000 件；合格供应商 A、B 到期可供分别为 450、350 件，其他供应商尚未准入。请制定采购建议。', 'A、B 建议量不超过 450、350 件，到期可供合计 800 件，明确 200 件缺口；不使用未准入来源补足，提出待确认处置建议。', ['供应不足', '边界条件'], 'V2'),
    makeCase(3, '采购需求缺失物料编码', '采购需求单 PR-203 数量 300 件，物料名称为“连接组件”，编码缺失；物料主数据中有两种规格同名记录。请开始寻源。', '识别物料编码缺失且无法唯一确定规格，暂停该项寻源，请求补充编码与规格，不按名称推断供应商和报价。', ['数据缺失', '异常处理'], 'V2'),
    makeCase(4, '最低报价供应商准入失效', '物料 M-004 需求 200 件。供应商 C 单价 90 元但准入资料已过期；A 单价 100 元且准入有效、可按期供 200 件。规则要求仅推荐准入有效供应商。', '不因 C 报价最低而纳入推荐；说明其准入失效证据，可建议 A 200 件并列明依据；C 需完成准入后另行评审。', ['准入合规', '规则校验'], 'V1'),
    makeCase(5, '迟交订单的合格替代来源', '物料 M-005 需求 600 件，要求 11 月 15 日到货；供应商 A 仅 400 件能按期交付，其余 200 件延期 5 天；已准入 B 可按期提供 200 件且报价有效。', '识别 A 的 200 件迟交与 5 天延期，建议 A 按期 400 件、B 替代 200 件；列明价格与准入依据，替代方案等待采购负责人确认。', ['交期风险', '替代供应商'], 'V2'),
    makeCase(6, '同口径比较含税与未税报价', '物料 M-006 需求 100 件；A 含税单价 113 元，B 未税单价 100 元、税率 13%，二者币种单位一致且均已准入。请比较报价。', '将 B 报价换算为含税 113 元后比较，两者价格相同；不将 B 错判为更低价来源，仍结合交期、质量与可供量评审。', ['报价口径', '税率校验', '边界条件'], 'V1'),
    makeCase(7, '报价版本与采购规则冲突', 'A 的已确认报价 V1 为 100 元，V2 报价草稿为 95 元但未审批；两条同优先级采购规则分别要求“最低价优先”和“固定份额不调整”。请输出最终推荐。', '明确 V1 为有效报价依据，列明两条规则的冲突影响；请求有权人员确认后再形成最终份额，不采用未审批 V2 或静默覆盖规则。', ['版本回归', '规则冲突', '人工确认'], 'V3', false),
    makeCase(8, '应用级供应风险摘要', '采购寻源方案 V3 中，关键物料仅有一家合格来源，到期仍有 200 件缺口；另有供应商准入异常待核实。请从采购管理应用视角形成风险与待办。', '覆盖单一来源、交付缺口和准入异常，引用方案与异常证据，明确责任人和审批节点；不自行批准例外准入、超预算采购或更改份额。', ['应用复核', '供应风险'], 'V2', false)
  ];

  const suite = (number, name, target, taskNumbers, caseNumbers) => ({
    id: id('ES', number), name, target, agentId: tasks.find(t => t.id === id('BT', taskNumbers[0])).agentId,
    taskIds: taskNumbers.map(n => id('BT', n)), caseIds: caseNumbers.map(n => id('EC', n)), createdAt: createdAt(suiteDays[number - 1])
  });
  const suites = sales ? [
    suite(1, '销售分货核心能力验收', '验证正常分货、库存不足、关键数据缺失、规则冲突和已确认订单保障，检查业务约束与结果完整性。', [1, 2, 3], [1, 2, 3, 4, 5]),
    suite(2, '库存边界与规则回归', '回归库存不足、零库存与规则版本处理，确认缺口计算正确且未确认规则不会直接生效。', [2, 3], [2, 6, 7]),
    suite(3, '销售应用风险复核', '检验应用 Agent 对分货缺口、规则冲突及版本风险的汇总、证据引用和人工确认边界。', [4], [2, 4, 7, 8])
  ] : [
    suite(1, '采购寻源核心能力验收', '验证供应商份额建议、供应不足、关键输入缺失、准入约束和迟交替代，检查采购方案的合规性与完整性。', [1, 2, 3], [1, 2, 3, 4, 5]),
    suite(2, '报价口径与规则回归', '回归准入有效性、含税与未税报价比较及规则版本冲突，避免错误推荐和未经确认的规则覆盖。', [1, 3], [4, 6, 7]),
    suite(3, '采购应用供应风险复核', '检验应用 Agent 对到期缺口、迟交、单一来源与规则冲突的汇总，明确责任、证据和审批节点。', [4], [2, 5, 7, 8])
  ];

  // Explicit illustrative coverage, separate for every suite and case membership.
  suites.forEach(s=>{
    s.taskSnapshots=JSON.parse(JSON.stringify(tasks.filter(t=>s.taskIds.includes(t.id))));
    s.caseBindings=Object.fromEntries(s.caseIds.map((caseId,index)=>{const task=s.taskSnapshots[index%s.taskSnapshots.length],dims=task.dimensions||[];return [caseId,[{taskId:task.id,dimensionNames:dims.length?[dims[index%dims.length].name]:[]}]];}));
  });

  return {scene, prefix, tasks, suites, cases, sequence: {task: 4, suite: 3, case: 8}};
}
